const pipeline = (x) => x();

const importers = [
  async (path) => {
    if (!/^\.[\\/](?:packages[\\/]ngblock(?:[\\/](?!\.)(?:(?:(?!(?:^|[\\/])\.).)*?)[\\/]|[\\/]|$)(?!\.)(?=.)[^\\/]*?\.(mdx|stories\.(js|jsx|ts|tsx)))$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(19);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?!.*node_modules)(?:[\\/]packages[\\/]ngblock(?:[\\/](?!\.)(?:(?:(?!(?:^|[\\/])\.).)*?)[\\/]|[\\/]|$)(?!\.)(?=.)[^\\/]*?\.(mdx|stories\.(js|jsx|ts|tsx)))$/ */
      './packages/ngblock/' + pathRemainder
    );
  }
  ,
  async (path) => {
    if (!/^\.[\\/](?:packages[\\/]ngblock[\\/]\.storybook[\\/](?!\.)(?=.)[^\\/]*?\.stories\.(js|jsx|ts|tsx))$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(30);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?!.*node_modules)(?:[\\/]packages[\\/]ngblock[\\/]\.storybook[\\/](?!\.)(?=.)[^\\/]*?\.stories\.(js|jsx|ts|tsx))$/ */
      './packages/ngblock/.storybook/' + pathRemainder
    );
  }
  
];

export async function importFn(path) {
  for (let i = 0; i < importers.length; i++) {
    const moduleExports = await pipeline(() => importers[i](path));
    if (moduleExports) {
      return moduleExports;
    }
  }
}